{"ideviceId":"idevice-1780672345604-m2sogkxyc","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<style>
        .contenedor-portada-limpia {
            max-width: 900px;
            margin: 50px auto;
            padding: 40px 20px;
            background-color: #ffffff; /* Fondo blanco limpio de la interfaz anterior */
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            text-align: center;
            box-sizing: border-box;
        }

        /* Etiqueta superior sutil */
        .portada-tagline {
            font-size: 12px;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: #64748b;
            font-weight: 700;
            margin-bottom: 20px;
            display: inline-block;
        }

        /* Título principal imponente */
        .portada-titulo-principal {
            font-size: 46px;
            font-weight: 850;
            color: #0f172a;
            line-height: 1.15;
            margin: 0 0 16px 0;
            letter-spacing: -1px;
            text-transform: uppercase;
        }

        /* Subtítulo descriptivo */
        .portada-subtitulo {
            font-size: 18px;
            color: #475569;
            margin: 0 auto 45px auto;
            max-width: 550px;
            font-weight: 400;
            line-height: 1.5;
        }

        /* Botón de acción con el estilo oscuro uniforme anterior */
        .btn-portada-accion {
            display: inline-block;
            background-color: #1e293b;
            color: #ffffff !important;
            padding: 14px 40px;
            border-radius: 8px;
            font-size: 13px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            text-decoration: none;
            transition: background-color 0.15s ease, transform 0.1s ease;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
        }

        .btn-portada-accion:hover {
            background-color: #0f172a;
            transform: translateY(-1px);
        }

        .btn-portada-accion:active {
            transform: scale(0.98);
        }

        /* Línea divisoria minimalista */
        .linea-separadora-portada {
            margin: 70px auto 35px auto;
            max-width: 150px;
            border: 0;
            border-top: 2px solid #e2e8f0;
        }

        /* Bloques de metadatos inferiores */
        .portada-creditos-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
            gap: 30px;
            max-width: 750px;
            margin: 0 auto;
        }

        .credito-item {
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .credito-label {
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #94a3b8;
            font-weight: 700;
            margin-bottom: 6px;
        }

        .credito-valor {
            font-size: 14px;
            color: #334155;
            font-weight: 600;
            margin: 0;
            line-height: 1.3;
        }
    </style>
