</div>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1780669999271-596w97has","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<style>
        .contenedor-launchpad-limpio {
            max-width: 1000px;
            margin: 0 auto;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            padding: 10px;
            background-color: #ffffff; /* Fondo blanco limpio de la interfaz anterior */
        }

        /* Título tipo insignia uniforme */
        .badge-titulo-launchpad {
            display: inline-block;
            background-color: #f1f5f9; 
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 10px 24px;
            margin-bottom: 30px;
        }

        .badge-titulo-launchpad h2 {
            margin: 0;
            font-size: 18px;
            color: #1e293b;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 700;
        }

        /* Cuadrícula responsiva de 4 columnas */
        .grid-modulos-limpio {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
        }

        @media (min-width: 1024px) {
            .grid-modulos-limpio {
                grid-template-columns: repeat(4, 1fr);
            }
        }

        /* Tarjeta de módulo basada en la forma anterior (gris claro muy sutil) */
        .tarjeta-modulo-limpia {
            background-color: #f8fafc;
            border: 1px solid #e2e8f0;
            border-radius: 12px;
            padding: 24px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            position: relative;
            overflow: hidden;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.02);
            transition: transform 0.2s ease, border-color 0.2s ease;
        }

        .tarjeta-modulo-limpia:hover {
            transform: translateY(-3px);
            border-color: #cbd5e1;
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.04);
        }

        /* Forma de la tarjeta: Borde acentuado a la izquierda */
        .tarjeta-modulo-limpia::before {
            content: '';
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 5px;
            background-color: #3b82f6; /* Azul por defecto */
        }

        /* Acento verde exclusivo para el módulo T3 */
        .tarjeta-modulo-limpia.acento-verde::before {
            background-color: #10b981;
        }

        /* Contenido de texto interno */
        .meta-modulo {
            font-size: 11px;
            color: #64748b;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 6px;
            display: block;
        }

        .titulo-modulo {
            font-size: 16px;
            color: #0f172a;
            font-weight: 800;
            margin: 0 0 6px 0;
            line-height: 1.3;
        }

        .autor-modulo {
            font-size: 13px;
            color: #b45309; /* Tono ocre/amarillo oscuro para contrastar sobre fondo claro */
            font-style: italic;
            margin: 0 0 25px 0;
        }

        /* Botón basado exactamente en el formato oscuro corporativo previo */
        .boton-modulo-limpio {
            display: block;
            width: 100%;
            text-align: center;
            background-color: #1e293b;
            color: #ffffff !important;
            padding: 11px 0;
            border-radius: 8px;
            font-size: 12px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            text-decoration: none;
            box-sizing: border-box;
            transition: background-color 0.15s ease;
            margin-top: auto;
        }

        .boton-modulo-limpio:hover {
            background-color: #0f172a;
        }

        .boton-modulo-limpio:active {
            transform: scale(0.98);
        }
    </style>
