<script>
        document.getElementById('btnIniciarModulo').addEventListener('click', function(e) {
            e.preventDefault(); 

            // Busca el botón "Siguiente" nativo de eXeLearning
            var botonSiguiente = document.querySelector('.next') || 
                                 document.querySelector('#node-next') || 
                                 document.querySelector('.next-page') ||
                                 document.querySelector('.toggle-next');

            if (botonSiguiente) {
                botonSiguiente.click(); 
            } else {
                // Alternativa por menú lateral si los botones inferiores no están activos
                var activo = document.querySelector('.active');
                if (activo && activo.nextElementSibling) {
                    var siguienteEnlace = activo.nextElementSibling.querySelector('a');
                    if (siguienteEnlace) siguienteEnlace.click();
                } else {
                    alert('Asigna la siguiente página en el menú o activa los botones de navegación inferiores.');
                }
            }
        });
    </script>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

