<div class="contenedor-titan">
<div class="badge-titulo-titan">
<h2>Titán: El Mundo Anaranjado</h2>
</div>
<div class="layout-columnas-titan">
<div class="columna-imagen-titan"><img src="https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/09/p/i/a/1/PIA14948-800w.jpg?w=800&h=799&fit=clip&crop=faces%2Cfocalpoint" alt="Fotografía de Titán - NASA" class="imagen-titan-nasa" /></div>
<div class="columna-contenido-titan">
