{"ideviceId":"idevice-1780640872933-q1ffwhahi","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<style>
        .contenedor-comparativa {
            max-width: 950px;
            margin: 0 auto;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            padding: 10px;
            background-color: #ffffff;
        }

        /* Título tipo insignia uniforme con los bocetos anteriores */
        .badge-titulo-comparativa {
            display: inline-block;
            background-color: #f1f5f9; 
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 10px 24px;
            margin-bottom: 25px;
        }

        .badge-titulo-comparativa h2 {
            margin: 0;
            font-size: 18px;
            color: #1e293b;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 700;
        }

        /* Contenedor adaptativo para la tabla */
        .tabla-responsiva {
            width: 100%;
            overflow-x: auto;
            border-radius: 14px;
            border: 1px solid #e2e8f0;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
        }

        /* Estilos de la Tabla */
        .tabla-mundos {
            width: 100%;
            border-collapse: collapse;
            text-align: left;
            background-color: #ffffff;
            min-width: 600px; /* Evita que se comprima demasiado en pantallas chicas */
        }

        .tabla-mundos th {
            background-color: #f8fafc;
            color: #475569;
            font-size: 14px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            padding: 16px 20px;
            border-bottom: 2px solid #e2e8f0;
        }

        .tabla-mundos td {
            padding: 18px 20px;
            border-bottom: 1px solid #f1f5f9;
            color: #334155;
            font-size: 15px;
            line-height: 1.5;
            vertical-align: top;
        }

        /* Filas alternas para mejorar la legibilidad */
        .tabla-mundos tr:nth-child(even) {
            background-color: #fcfcfc;
        }

        .tabla-mundos tr:hover {
            background-color: #f8fafc;
        }

        /* Identificadores visuales con los colores pedagógicos del boceto */
        .satelite-luna {
            color: #b45309; /* Dorado/Ámbar corporativo y legible */
            font-weight: 700;
            font-size: 16px;
        }

        .satelite-titan {
            color: #c2410c; /* Naranja/Rojizo quemado elegante */
            font-weight: 700;
            font-size: 16px;
        }

        .satelite-europa {
            color: #0f766e; /* Verde azulado/Teal profundo profesional */
            font-weight: 700;
            font-size: 16px;
        }

        .planeta-nombre {
            font-weight: 500;
            color: #64748b;
        }
    </style>
<div class="contenedor-comparativa">
<div class="badge-titulo-comparativa">
<h2>Comparativa de los 3 satelites</h2>
</div>
<div class="tabla-responsiva">
<table class="tabla-mundos">
<thead>
<tr>
<th style="width: 15%;">Satélite</th>
<th style="width: 15%;">Planeta</th>
<th style="width: 35%;">Superficie / Rasgo principal</th>
<th style="width: 35%;">Dato clave</th>
</tr>
</thead>
<tbody>
<tr>
<td><span class="satelite-luna">La Luna</span></td>
<td><span class="planeta-nombre">Tierra</span></td>
<td>Rocosa, repleta de cráteres (sin atmósfera).</td>
<td><strong>Controla las mareas</strong> y estabiliza el eje terrestre.</td>
</tr>
<tr>
<td><span class="satelite-titan">Titán</span></td>
<td><span class="planeta-nombre">Saturno</span></td>
<td>Atmósfera densa anaranjada (Nitrógeno).</td>
<td><strong>Lagos y ríos estables</strong> de metano líquido.</td>
</tr>
<tr>
<td><span class="satelite-europa">Europa</span></td>
<td><span class="planeta-nombre">Júpiter</span></td>
<td>Corteza lisa de hielo brillante con fracturas.</td>
<td><strong>Océano de agua salada oculto</strong> (fricción gravitacional).</td>
</tr>
</tbody>
</table>
</div>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1780643397319-g8l0m4imw","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<style>
        .contenedor-reflexion {
            max-width: 950px;
            margin: 0 auto;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            padding: 10px;
            background-color: #ffffff;
        }

        /* Título tipo insignia uniforme con el resto del módulo */
        .badge-titulo-reflexion {
            display: inline-block;
            background-color: #f1f5f9; 
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 10px 24px;
            margin-bottom: 25px;
        }

        .badge-titulo-reflexion h2 {
            margin: 0;
            font-size: 18px;
            color: #1e293b;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 700;
        }

        /* Tarjeta principal de la actividad */
        .tarjeta-actividad {
            background-color: #f8fafc;
            border: 1px solid #e2e8f0;
            border-radius: 16px;
            padding: 35px 40px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.02);
        }

        /* Textos de la consigna */
        .consigna-principal {
            font-size: 18px;
            color: #0f172a;
            font-weight: 700;
            margin: 0 0 15px 0;
            line-height: 1.4;
        }

        .consigna-secundaria {
            font-size: 16px;
            color: #475569;
            line-height: 1.6;
            margin: 0 0 25px 0;
        }

        /* Área de texto (Textarea) interactiva */
        .area-reflexion {
            width: 100%;
            min-height: 120px;
            padding: 16px;
            font-family: inherit;
            font-size: 15px;
            color: #334155;
            background-color: #ffffff;
            border: 2px solid #cbd5e1;
            border-radius: 10px;
            box-sizing: border-box;
            resize: vertical; /* Permite al alumno estirar la caja hacia abajo si escribe mucho */
            transition: border-color 0.2s ease, box-shadow 0.2s ease;
            margin-bottom: 25px;
        }

        .area-reflexion::placeholder {
            color: #94a3b8;
            font-style: italic;
        }

        /* Efecto visual cuando el estudiante hace clic para escribir */
        .area-reflexion:focus {
            outline: none;
            border-color: #64748b;
            box-shadow: 0 0 0 3px rgba(100, 116, 139, 0.15);
        }

        /* Botón de Continuar alineado a la izquierda como en el diseño de referencia */
        .contenedor-boton {
            display: flex;
            justify-content: flex-start;
        }

        .boton-continuar {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 13px 24px;
            background-color: #1e293b;
            color: #ffffff;
            text-decoration: none;
            font-size: 14px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            border-radius: 8px;
            transition: background-color 0.15s ease, transform 0.1s ease;
        }

        .boton-continuar:hover {
            background-color: #0f172a;
        }

        .boton-continuar:active {
            transform: scale(0.98);
        }
    </style>
<div class="contenedor-reflexion">
<div class="badge-titulo-reflexion">
<h2>Piensa y Responde</h2>
</div>
<div class="tarjeta-actividad">
<p class="consigna-principal">Imagina que la Tierra nunca hubiera chocado con el protoplaneta Theia y no tuviéramos a la Luna.</p>
<p class="consigna-secundaria">Basándote en los efectos de su fuerza gravitatoria, ¿cómo crees que sería la vida en la Tierra (o los océanos) si no existiera nuestro satélite natural?</p>
<textarea class="area-reflexion" placeholder="Escribe tu reflexión aquí... (mínimo 20 palabras)"></textarea><br /></div>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1780641589268-vga2ovj5f","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<style>
        .contenedor-misiones {
            max-width: 950px;
            margin: 0 auto;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            padding: 10px;
            background-color: #ffffff;
        }

        /* Título de la sección tipo insignia */
        .badge-titulo-misiones {
            display: inline-block;
            background-color: #f1f5f9; 
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 10px 24px;
            margin-bottom: 30px;
        }

        .badge-titulo-misiones h2 {
            margin: 0;
            font-size: 18px;
            color: #1e293b;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 700;
        }

        /* Contenedor de las dos fases en paralelo */
        .grid-misiones {
            display: flex;
            gap: 25px;
            flex-wrap: wrap; /* Soporte para dispositivos móviles */
        }

        /* Tarjetas de cada fase */
        .tarjeta-mision {
            flex: 1;
            min-width: 280px;
            background-color: #ffffff;
            border: 1px solid #e2e8f0;
            border-radius: 16px;
            padding: 28px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.02), 0 2px 4px -1px rgba(0, 0, 0, 0.01);
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            align-items: flex-start;
            transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
        }

        .tarjeta-mision:hover {
            transform: translateY(-2px);
            border-color: #cbd5e1;
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.04);
        }

        /* Encabezados internos de las fases */
        .mision-header {
            margin-bottom: 14px;
            display: flex;
            align-items: center;
