<div style="font-family: sans-serif; background: #ffffff; padding: 20px; display: flex; justify-content: center;">
<div class="dd1-tarjeta" id="dd1-caja">
<p style="color: #102a43; font-weight: 600; margin-top: 0;">El punto exacto de la órbita en el que un cuerpo celeste se encuentra a la menor distancia posible del Sol se denomina:</p>
<select class="dd1-select" id="dd1-sel">
<option value="">-- Selecciona una opción --</option>
<option value="Afelio">Afelio</option>
<option value="Perihelio">Perihelio</option>
<option value="Perigeo">Perigeo</option>
</select><button class="dd1-btn" onclick="evaluar_dd1()">Evaluar Respuesta</button>
<div id="dd1-feed" class="dd1-feedback"></div>
</div>
<script>
        function evaluar_dd1() {
            const res = document.getElementById('dd1-sel').value;
            const feed = document.getElementById('dd1-feed');
            const caja = document.getElementById('dd1-caja');
            if(!res) return alert("Selecciona una opción");
            feed.style.display = "block";
            if(res === "Perihelio") {
                feed.innerHTML = "¡Correcto! El Perihelio es el punto más cercano al Sol. (Perigeo es respecto a la Tierra).";
                feed.style.background = "#d1fae5"; feed.style.color = "#065f46"; caja.style.borderLeftColor = "#34d399";
            } else {
                feed.innerHTML = "Incorrecto. La respuesta correcta es Perihelio. El Afelio es el punto más lejano.";
                feed.style.background = "#fee2e2"; feed.style.color = "#991b1b"; caja.style.borderLeftColor = "#f87171";
            }
        }
    </script>
</div>","feedbackRight":"","feedbackWrong":"","suggestion":"","wrongAnswersValue":"","selectionType":"single","answers":[],"answer":"1","capitalization":false,"strict":false,"order":0,"customScore":1,"time":0},{"id":"1780675370032-Q23YB","activityType":"dropdown","baseText":"<style>
