                feedback.style.background = "#d1fae5"; feedback.style.color = "#065f46"; feedback.style.border = "1px solid #34d399";
                tarjeta.style.borderLeftColor = "#34d399";
            } else { // Eligió Verdadero (Error)
                feedback.innerHTML = "¡Incorrecto! Es un Mito. La cola apunta siempre en dirección opuesta al Sol impulsada por el viento solar, no hacia atrás de su propia trayectoria.";
                feedback.style.background = "#fee2e2"; feedback.style.color = "#991b1b"; feedback.style.border = "1px solid #f87171";
                tarjeta.style.borderLeftColor = "#f87171";
            }
            feedback.style.display = "block";
        }
    </script>
</div>","feedbackRight":"","feedbackWrong":"","suggestion":"","wrongAnswersValue":"","selectionType":"single","answers":[],"answer":"0","capitalization":false,"strict":false,"order":0,"customScore":1,"time":0},{"id":"1780674747551-ER4LY","activityType":"true-false","baseText":"<style>
