        function responder_vfc5(respuestaVerdadera) {
            document.getElementById('vfc5-botones').style.display = 'none';
            const feedback = document.getElementById('vfc5-feedback');
            const tarjeta = document.getElementById('vfc5-tarjeta');

            if(respuestaVerdadera === false) { // Falso es lo correcto
                feedback.innerHTML = "¡Exacto! Es Falso. La composición no define a un planeta. Plutón fue degradado porque falló en la regla de 'limpiar su vecindario orbital' al compartir zona con miles de objetos helados.";
