                tarjeta.style.borderLeftColor = "#34d399";
            } else { // Eligió Verdadero (Error)
                feedback.innerHTML = "¡Incorrecto! Es un Mito muy común. Plutón no fue degradado por estar hecho de hielo, sino porque no tiene suficiente gravedad para 'limpiar su vecindario' de otros objetos.";
                feedback.style.background = "#fee2e2"; feedback.style.color = "#991b1b"; feedback.style.border = "1px solid #f87171";
                tarjeta.style.borderLeftColor = "#f87171";
            }
            feedback.style.display = "block";
        }
    </script>
