            const seleccionado = document.getElementById('q1-' + opcion);

            if(opcion === 'B') {
                seleccionado.style.background = "#d1fae5"; seleccionado.style.borderColor = "#34d399";
                feedback.innerHTML = "¡Correcto! Hemos abstraído el concepto a su composición sólida, que es la característica esencial de la Tierra y Marte.";
