            } else {
                seleccionado.style.background = "#fee2e2"; seleccionado.style.borderColor = "#f87171";
                feedback.innerHTML = "Incorrecto. Los planetas seleccionados son gaseosos o gigantes de hielo, no encajan en el modelo de superficie sólida.";
                feedback.style.background = "#fee2e2"; feedback.style.color = "#991b1b"; feedback.style.border = "1px solid #f87171";
            }
            feedback.style.display = "block";
        }
    </script>
